import{_ as i,o as a,c as t,a0 as n}from"./chunks/framework.Dx25mwie.js";const h=JSON.parse('{"title":"SCALE LXP Information Security Policy","description":"","frontmatter":{},"headers":[],"relativePath":"policies/hecvat-information-security-policy.md","filePath":"policies/hecvat-information-security-policy.md"}'),r={name:"policies/hecvat-information-security-policy.md"};function o(s,e,l,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="scale-lxp-information-security-policy" tabindex="-1">SCALE LXP Information Security Policy <a class="header-anchor" href="#scale-lxp-information-security-policy" aria-label="Permalink to &quot;SCALE LXP Information Security Policy&quot;">​</a></h1><p><strong>Document owner:</strong> Security / Engineering Leadership<br><strong>Approved by:</strong> [Insert approver]<br><strong>Effective date:</strong> [Insert date]<br><strong>Review cadence:</strong> At least annually and upon material changes to systems, vendors, risks, or regulatory obligations<br><strong>Applies to:</strong> SCALE LXP personnel, contractors, systems, services, production environments, and third parties with authorized access to SCALE LXP data or systems</p><h2 id="_1-purpose" tabindex="-1">1. Purpose <a class="header-anchor" href="#_1-purpose" aria-label="Permalink to &quot;1. Purpose&quot;">​</a></h2><p>This Information Security Policy defines the administrative, technical, and operational safeguards used to protect SCALE LXP systems and data. It is intended to support institutional security reviews, including the Higher Education Community Vendor Assessment Toolkit (HECVAT), by documenting how SCALE LXP governs information security, protects customer data, manages risk, and responds to security events.</p><p>SCALE LXP is a classroom-based supply chain simulation platform. The platform supports instructors and students through class management, scenario configuration, student submissions, AI-assisted simulation processing, ledger generation, dashboards, and email notifications.</p><h2 id="_2-scope" tabindex="-1">2. Scope <a class="header-anchor" href="#_2-scope" aria-label="Permalink to &quot;2. Scope&quot;">​</a></h2><p>This policy applies to:</p><ul><li>Production, staging, development, and administrative systems that support SCALE LXP.</li><li>Application services, APIs, background workers, queues, databases, authentication integrations, email integrations, and AI integrations.</li><li>Customer data, student data, instructor data, operational data, logs, secrets, configuration, and support data.</li><li>Employees, contractors, service providers, and vendors who access SCALE LXP systems or data.</li></ul><p>The current SCALE LXP technical environment includes Node.js, Express, MongoDB, Clerk, SendGrid, OpenAI, Bull/Redis queues, Docker, and DigitalOcean App Platform.</p><h2 id="_3-security-governance" tabindex="-1">3. Security Governance <a class="header-anchor" href="#_3-security-governance" aria-label="Permalink to &quot;3. Security Governance&quot;">​</a></h2><p>SCALE LXP maintains an information security program appropriate to the size, maturity, and risk profile of the organization. Security responsibilities are assigned to designated leadership responsible for:</p><ul><li>Approving and maintaining security policies.</li><li>Reviewing security risks and remediation plans.</li><li>Overseeing access control, vulnerability management, incident response, vendor risk, and data protection practices.</li><li>Ensuring personnel understand their security responsibilities.</li><li>Reviewing material security changes before deployment where appropriate.</li></ul><p>Security policies and procedures are reviewed at least annually and updated when there are significant changes to the business, technology stack, threat landscape, or applicable legal and contractual obligations.</p><h2 id="_4-risk-management" tabindex="-1">4. Risk Management <a class="header-anchor" href="#_4-risk-management" aria-label="Permalink to &quot;4. Risk Management&quot;">​</a></h2><p>SCALE LXP performs risk management activities to identify, evaluate, and address risks to confidentiality, integrity, availability, and privacy. Risk management activities include:</p><ul><li>Maintaining an inventory of material systems, services, data stores, and vendors.</li><li>Reviewing risks associated with application changes, infrastructure changes, new vendors, and new data processing activities.</li><li>Prioritizing remediation based on likelihood, impact, exploitability, and data sensitivity.</li><li>Tracking accepted risks, remediation owners, target dates, and status.</li><li>Reviewing high-risk findings with management.</li></ul><p>Risk treatment may include remediation, mitigation, transfer, acceptance, or avoidance. Accepted risks must be documented and approved by appropriate leadership.</p><h2 id="_5-data-classification-and-handling" tabindex="-1">5. Data Classification and Handling <a class="header-anchor" href="#_5-data-classification-and-handling" aria-label="Permalink to &quot;5. Data Classification and Handling&quot;">​</a></h2><p>SCALE LXP classifies data based on sensitivity and business impact. At minimum, SCALE LXP recognizes the following data categories:</p><ul><li><strong>Public:</strong> Information approved for public release.</li><li><strong>Internal:</strong> Operational information intended for authorized personnel.</li><li><strong>Confidential:</strong> Customer, student, instructor, class, organization, business, security, or support data not intended for public disclosure.</li><li><strong>Restricted:</strong> Secrets, credentials, authentication tokens, encryption keys, highly sensitive security data, and other data requiring strict access controls.</li></ul><p>Personnel must handle data according to its classification. Confidential and Restricted data must be accessed only for authorized business purposes, stored in approved systems, transmitted through approved encrypted channels, and shared only with authorized recipients.</p><h2 id="_6-access-control" tabindex="-1">6. Access Control <a class="header-anchor" href="#_6-access-control" aria-label="Permalink to &quot;6. Access Control&quot;">​</a></h2><p>Access to SCALE LXP systems and data is granted based on least privilege, role-based need, and authorization by appropriate personnel.</p><p>SCALE LXP access control requirements include:</p><ul><li>Unique user accounts for workforce and administrative access.</li><li>Role-based access control for application users.</li><li>Separation between student/member and instructor/admin capabilities.</li><li>No super admin role in the application model unless a future operational requirement is formally approved and documented.</li><li>Multi-factor authentication for administrative and workforce systems where supported.</li><li>Timely removal or disabling of access when personnel leave or no longer require access.</li><li>Periodic review of privileged and sensitive access.</li><li>Prohibition on shared accounts except for approved service accounts with documented ownership and controls.</li></ul><p>Production access is limited to authorized personnel with a business need. Administrative actions should be logged where technically feasible.</p><h2 id="_7-authentication-and-authorization" tabindex="-1">7. Authentication and Authorization <a class="header-anchor" href="#_7-authentication-and-authorization" aria-label="Permalink to &quot;7. Authentication and Authorization&quot;">​</a></h2><p>SCALE LXP uses Clerk for user authentication and organization membership management. Application authorization is enforced by backend services and middleware that validate identity, organization scope, class membership, and role permissions before allowing access to protected resources.</p><p>Authentication and authorization controls include:</p><ul><li>Authentication required for protected application routes.</li><li>Authorization checks for organization-scoped, classroom-scoped, and role-scoped resources.</li><li>Administrative capabilities restricted to authorized instructor/admin users.</li><li>Student/member users restricted to their own authorized class, store, submission, results, and leaderboard views.</li><li>Webhook verification for trusted external event sources where supported.</li><li>Session and token handling aligned with the authentication provider&#39;s security features.</li></ul><h2 id="_8-passwords-secrets-and-key-management" tabindex="-1">8. Passwords, Secrets, and Key Management <a class="header-anchor" href="#_8-passwords-secrets-and-key-management" aria-label="Permalink to &quot;8. Passwords, Secrets, and Key Management&quot;">​</a></h2><p>Personnel must not store secrets, passwords, API keys, tokens, or private keys in source code, issue trackers, documentation, chat, or other unauthorized locations.</p><p>Secrets management requirements include:</p><ul><li>Store secrets only in approved secret management systems, deployment environment variables, or managed platform configuration.</li><li>Scope service credentials to the minimum required permissions.</li><li>Rotate credentials when compromise is suspected, when personnel with access leave, or on a defined risk-based schedule.</li><li>Remove unused credentials promptly.</li><li>Restrict access to production secrets to authorized personnel.</li><li>Review source control history and dependency configuration for accidental secret exposure when risk indicators are identified.</li></ul><h2 id="_9-encryption" tabindex="-1">9. Encryption <a class="header-anchor" href="#_9-encryption" aria-label="Permalink to &quot;9. Encryption&quot;">​</a></h2><p>SCALE LXP protects data in transit and at rest using encryption appropriate to the system and data sensitivity.</p><p>Encryption requirements include:</p><ul><li>Use TLS for external application traffic and API communications.</li><li>Use encrypted connections for administrative access where supported.</li><li>Use platform or database encryption at rest for production data stores where supported by the hosting and database providers.</li><li>Protect credentials, tokens, and secrets through approved storage mechanisms.</li><li>Avoid transmitting Confidential or Restricted data through unencrypted or unauthorized channels.</li></ul><p>Encryption controls are reviewed when hosting, database, or vendor architecture changes.</p><h2 id="_10-secure-software-development" tabindex="-1">10. Secure Software Development <a class="header-anchor" href="#_10-secure-software-development" aria-label="Permalink to &quot;10. Secure Software Development&quot;">​</a></h2><p>SCALE LXP follows secure software development practices for application and infrastructure changes. Engineering practices include:</p><ul><li>Source code maintained in version control.</li><li>Peer review for material code changes.</li><li>Branch protection or equivalent review controls where feasible.</li><li>Testing appropriate to the risk of the change.</li><li>Separation of development, staging, and production environments where feasible.</li><li>Secure handling of configuration and environment variables.</li><li>Review of authentication, authorization, input validation, data access, and logging behavior for security-sensitive changes.</li><li>Dependency management and remediation of known vulnerable packages based on severity and exploitability.</li></ul><p>Security-sensitive changes, including changes to authentication, authorization, data access, ledger processing, background jobs, or external integrations, should receive additional review.</p><h2 id="_11-change-management" tabindex="-1">11. Change Management <a class="header-anchor" href="#_11-change-management" aria-label="Permalink to &quot;11. Change Management&quot;">​</a></h2><p>SCALE LXP manages changes to production systems to reduce the risk of unauthorized, untested, or disruptive modifications.</p><p>Change management expectations include:</p><ul><li>Documenting material changes through pull requests, tickets, commits, or release notes.</li><li>Reviewing and approving changes before production deployment.</li><li>Testing changes before release according to risk.</li><li>Maintaining rollback or remediation procedures for failed deployments.</li><li>Documenting emergency changes after implementation, including the reason, approver, impact, and follow-up actions.</li></ul><h2 id="_12-vulnerability-and-patch-management" tabindex="-1">12. Vulnerability and Patch Management <a class="header-anchor" href="#_12-vulnerability-and-patch-management" aria-label="Permalink to &quot;12. Vulnerability and Patch Management&quot;">​</a></h2><p>SCALE LXP identifies and remediates vulnerabilities in application code, dependencies, infrastructure, and third-party services using a risk-based approach.</p><p>Vulnerability management activities include:</p><ul><li>Monitoring dependency and platform security advisories.</li><li>Running dependency, static analysis, or other security checks where feasible.</li><li>Prioritizing remediation based on severity, exploitability, exposure, and data sensitivity.</li><li>Applying vendor patches and runtime updates according to risk.</li><li>Tracking remediation actions for high-risk findings.</li><li>Performing security testing or third-party review when warranted by customer, institutional, or product risk.</li></ul><p>Target remediation timeframes should be defined by severity. Critical and actively exploited vulnerabilities affecting production systems should be addressed as soon as practicable.</p><h2 id="_13-logging-and-monitoring" tabindex="-1">13. Logging and Monitoring <a class="header-anchor" href="#_13-logging-and-monitoring" aria-label="Permalink to &quot;13. Logging and Monitoring&quot;">​</a></h2><p>SCALE LXP maintains logs to support troubleshooting, security monitoring, auditability, and incident investigation. Logging practices should balance operational needs with data minimization and privacy requirements.</p><p>Logging and monitoring controls include:</p><ul><li>Capture application, authentication, authorization, administrative, job processing, and error events where feasible.</li><li>Restrict log access to authorized personnel.</li><li>Avoid logging secrets, credentials, full tokens, or unnecessary sensitive personal data.</li><li>Monitor production health, job failures, queue processing, and application errors.</li><li>Review security-relevant alerts and anomalies based on severity.</li><li>Retain logs according to operational, contractual, legal, and security needs.</li></ul><h2 id="_14-incident-response" tabindex="-1">14. Incident Response <a class="header-anchor" href="#_14-incident-response" aria-label="Permalink to &quot;14. Incident Response&quot;">​</a></h2><p>SCALE LXP maintains an incident response process for identifying, triaging, containing, investigating, remediating, and communicating security incidents.</p><p>The incident response process includes:</p><ul><li>Designated incident owners and escalation contacts.</li><li>Severity classification based on data sensitivity, scope, customer impact, service impact, and regulatory or contractual obligations.</li><li>Containment steps such as credential rotation, access revocation, disabling affected services, or blocking malicious activity.</li><li>Investigation and evidence preservation appropriate to the incident.</li><li>Customer, institutional, vendor, legal, or regulatory notification when required.</li><li>Post-incident review and corrective action tracking.</li></ul><p>Personnel must promptly report suspected security incidents, unauthorized access, data exposure, credential compromise, malware, phishing, or suspicious activity.</p><h2 id="_15-business-continuity-disaster-recovery-and-availability" tabindex="-1">15. Business Continuity, Disaster Recovery, and Availability <a class="header-anchor" href="#_15-business-continuity-disaster-recovery-and-availability" aria-label="Permalink to &quot;15. Business Continuity, Disaster Recovery, and Availability&quot;">​</a></h2><p>SCALE LXP maintains practices intended to preserve service availability and recover from disruptions affecting critical systems.</p><p>Availability and recovery practices include:</p><ul><li>Use of managed hosting and database providers for production infrastructure.</li><li>Monitoring of application availability and background job processing.</li><li>Backup or restoration capabilities for critical production data where supported by the database and hosting architecture.</li><li>Defined recovery expectations for material systems.</li><li>Review of service disruptions and corrective actions.</li><li>Vendor dependency review for critical services such as hosting, authentication, email, database, queueing, and AI processing.</li></ul><p>Recovery time objectives (RTOs) and recovery point objectives (RPOs) should be documented and reviewed as institutional or contractual requirements mature.</p><h2 id="_16-data-retention-and-disposal" tabindex="-1">16. Data Retention and Disposal <a class="header-anchor" href="#_16-data-retention-and-disposal" aria-label="Permalink to &quot;16. Data Retention and Disposal&quot;">​</a></h2><p>SCALE LXP retains data only as long as needed for educational, operational, contractual, legal, security, or support purposes.</p><p>Retention and disposal requirements include:</p><ul><li>Define retention expectations for customer data, class data, student submissions, ledger entries, logs, backups, and support records.</li><li>Delete or de-identify data when it is no longer required and deletion is contractually, legally, and technically permitted.</li><li>Securely dispose of credentials, tokens, and temporary exports when no longer needed.</li><li>Follow customer or institutional data deletion requests according to contract terms and applicable law.</li><li>Ensure backups age out according to provider capabilities and retention settings.</li></ul><h2 id="_17-privacy-and-student-data-protection" tabindex="-1">17. Privacy and Student Data Protection <a class="header-anchor" href="#_17-privacy-and-student-data-protection" aria-label="Permalink to &quot;17. Privacy and Student Data Protection&quot;">​</a></h2><p>SCALE LXP is designed for educational use and may process student, instructor, class, organization, and simulation data. SCALE LXP protects personal data through access controls, purpose limitation, data minimization, and contractual safeguards.</p><p>Privacy requirements include:</p><ul><li>Collect and process data only for authorized educational, operational, support, security, and service improvement purposes.</li><li>Limit student access to their own authorized data and permitted class-level views.</li><li>Limit instructor access to classes and students they are authorized to manage.</li><li>Do not sell student personal information.</li><li>Do not use customer data for unrelated advertising purposes.</li><li>Support institutional requests related to access, correction, deletion, or export where contractually and legally applicable.</li><li>Review new data uses, analytics, AI processing, or vendor integrations for privacy impact.</li></ul><h2 id="_18-artificial-intelligence-and-data-processing" tabindex="-1">18. Artificial Intelligence and Data Processing <a class="header-anchor" href="#_18-artificial-intelligence-and-data-processing" aria-label="Permalink to &quot;18. Artificial Intelligence and Data Processing&quot;">​</a></h2><p>SCALE LXP uses OpenAI to calculate simulation outcomes based on store configuration, scenario data, outcome data, student submissions, and ledger history. AI processing is used to support educational simulation outcomes and narrative feedback.</p><p>AI processing requirements include:</p><ul><li>Send only the data reasonably necessary to perform the simulation task.</li><li>Do not include unnecessary secrets, credentials, or unrelated personal data in AI prompts.</li><li>Use structured outputs where feasible to support deterministic processing.</li><li>Review AI-generated outputs through application workflows and instructor controls where appropriate.</li><li>Maintain instructor authority over scenario outcomes and ledger overrides.</li><li>Evaluate material changes to AI providers, models, prompts, or data use for security and privacy impact.</li></ul><h2 id="_19-vendor-and-third-party-risk-management" tabindex="-1">19. Vendor and Third-Party Risk Management <a class="header-anchor" href="#_19-vendor-and-third-party-risk-management" aria-label="Permalink to &quot;19. Vendor and Third-Party Risk Management&quot;">​</a></h2><p>SCALE LXP relies on third-party service providers for hosting, authentication, email delivery, database or infrastructure services, AI processing, development tooling, and related business operations.</p><p>Vendor risk management expectations include:</p><ul><li>Maintain an inventory of critical vendors and subprocessors.</li><li>Review vendor security, privacy, availability, and compliance posture based on risk.</li><li>Execute appropriate contracts, data protection terms, or security addenda where required.</li><li>Limit vendor access and data sharing to authorized purposes.</li><li>Review critical vendors periodically or when material service changes occur.</li><li>Remove vendor access or data integrations when no longer needed.</li></ul><p>Material vendors may include DigitalOcean, MongoDB or managed database providers, Clerk, SendGrid, OpenAI, GitHub or source control providers, and monitoring or support tooling.</p><h2 id="_20-personnel-security-and-training" tabindex="-1">20. Personnel Security and Training <a class="header-anchor" href="#_20-personnel-security-and-training" aria-label="Permalink to &quot;20. Personnel Security and Training&quot;">​</a></h2><p>SCALE LXP personnel and contractors with access to company systems or customer data must understand and follow security responsibilities.</p><p>Personnel security practices include:</p><ul><li>Security expectations communicated during onboarding.</li><li>Role-appropriate access provisioning.</li><li>Confidentiality obligations for personnel and contractors.</li><li>Security awareness training appropriate to role and risk.</li><li>Prompt offboarding and access removal.</li><li>Reporting obligations for suspected incidents, phishing, lost devices, unauthorized access, or policy violations.</li></ul><h2 id="_21-endpoint-and-device-security" tabindex="-1">21. Endpoint and Device Security <a class="header-anchor" href="#_21-endpoint-and-device-security" aria-label="Permalink to &quot;21. Endpoint and Device Security&quot;">​</a></h2><p>Personnel devices used to access SCALE LXP systems must be protected against unauthorized access and compromise.</p><p>Endpoint security expectations include:</p><ul><li>Use supported operating systems and keep devices patched.</li><li>Enable screen lock and local authentication.</li><li>Use disk encryption where supported.</li><li>Protect devices from malware and unauthorized software.</li><li>Do not store customer exports or Restricted data locally unless necessary and approved.</li><li>Report lost, stolen, or compromised devices promptly.</li></ul><h2 id="_22-network-and-infrastructure-security" tabindex="-1">22. Network and Infrastructure Security <a class="header-anchor" href="#_22-network-and-infrastructure-security" aria-label="Permalink to &quot;22. Network and Infrastructure Security&quot;">​</a></h2><p>SCALE LXP uses managed hosting and platform services to reduce infrastructure management risk. Infrastructure security expectations include:</p><ul><li>Restrict production administrative access to authorized personnel.</li><li>Use secure protocols for administrative access.</li><li>Restrict inbound and outbound access based on service need where supported.</li><li>Segregate environments and services where feasible.</li><li>Store production configuration securely.</li><li>Review infrastructure and deployment configuration for material changes.</li><li>Monitor provider security notices and apply required updates or configuration changes.</li></ul><h2 id="_23-backup-and-recovery" tabindex="-1">23. Backup and Recovery <a class="header-anchor" href="#_23-backup-and-recovery" aria-label="Permalink to &quot;23. Backup and Recovery&quot;">​</a></h2><p>SCALE LXP maintains backup and restoration practices for critical data based on provider capabilities and business requirements.</p><p>Backup requirements include:</p><ul><li>Identify critical data stores requiring backup or restore capability.</li><li>Protect backups from unauthorized access.</li><li>Encrypt backups where supported.</li><li>Test restore procedures periodically or after material architecture changes.</li><li>Document backup retention periods and recovery expectations.</li><li>Ensure deleted data ages out of backups according to retention settings and technical feasibility.</li></ul><h2 id="_24-acceptable-use" tabindex="-1">24. Acceptable Use <a class="header-anchor" href="#_24-acceptable-use" aria-label="Permalink to &quot;24. Acceptable Use&quot;">​</a></h2><p>Personnel must use SCALE LXP systems, data, devices, and accounts responsibly and only for authorized business purposes.</p><p>Prohibited activities include:</p><ul><li>Unauthorized access to systems or data.</li><li>Sharing credentials or bypassing access controls.</li><li>Storing secrets in unauthorized systems.</li><li>Introducing malicious code.</li><li>Exfiltrating customer, student, instructor, or company data.</li><li>Using production data in local or development environments unless approved and protected.</li><li>Connecting unapproved third-party tools to production systems or customer data.</li></ul><h2 id="_25-physical-and-environmental-security" tabindex="-1">25. Physical and Environmental Security <a class="header-anchor" href="#_25-physical-and-environmental-security" aria-label="Permalink to &quot;25. Physical and Environmental Security&quot;">​</a></h2><p>SCALE LXP primarily relies on managed cloud and platform providers for physical security of production infrastructure. Provider physical security controls are evaluated as part of vendor risk management.</p><p>For company-managed workspaces or devices, personnel must take reasonable precautions to protect devices, printed material, credentials, and confidential information from unauthorized access, loss, or theft.</p><h2 id="_26-compliance-and-institutional-reviews" tabindex="-1">26. Compliance and Institutional Reviews <a class="header-anchor" href="#_26-compliance-and-institutional-reviews" aria-label="Permalink to &quot;26. Compliance and Institutional Reviews&quot;">​</a></h2><p>SCALE LXP supports customer and institutional security reviews, including HECVAT, by maintaining security documentation and providing reasonable evidence of implemented controls.</p><p>Relevant evidence may include:</p><ul><li>Security policies and review history.</li><li>Architecture and data flow summaries.</li><li>Vendor and subprocessor inventory.</li><li>Access control procedures and review evidence.</li><li>Change management evidence.</li><li>Vulnerability management records.</li><li>Incident response procedures.</li><li>Backup and recovery documentation.</li><li>Privacy and data retention documentation.</li></ul><p>SCALE LXP will review institutional security requirements and contractual obligations before committing to additional controls, certifications, data processing terms, or service-level obligations.</p><h2 id="_27-exceptions" tabindex="-1">27. Exceptions <a class="header-anchor" href="#_27-exceptions" aria-label="Permalink to &quot;27. Exceptions&quot;">​</a></h2><p>Exceptions to this policy must be documented, risk-assessed, time-bound where practical, and approved by appropriate leadership. Exceptions should include:</p><ul><li>Description of the exception.</li><li>Business justification.</li><li>Affected systems, data, or users.</li><li>Compensating controls.</li><li>Expiration or review date.</li><li>Approval record.</li></ul><h2 id="_28-enforcement" tabindex="-1">28. Enforcement <a class="header-anchor" href="#_28-enforcement" aria-label="Permalink to &quot;28. Enforcement&quot;">​</a></h2><p>Violations of this policy may result in access revocation, disciplinary action, contract termination, legal action, customer notification, or other remediation depending on severity, impact, and applicable obligations.</p><h2 id="_29-policy-review-and-maintenance" tabindex="-1">29. Policy Review and Maintenance <a class="header-anchor" href="#_29-policy-review-and-maintenance" aria-label="Permalink to &quot;29. Policy Review and Maintenance&quot;">​</a></h2><p>This policy must be reviewed at least annually and when material changes occur to SCALE LXP systems, vendors, data processing activities, security risks, or legal and contractual obligations. Updates must be approved by designated leadership and communicated to affected personnel.</p><h2 id="_30-revision-history" tabindex="-1">30. Revision History <a class="header-anchor" href="#_30-revision-history" aria-label="Permalink to &quot;30. Revision History&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Description</th><th>Owner</th></tr></thead><tbody><tr><td>1.0</td><td>[Insert date]</td><td>Initial HECVAT information security policy draft</td><td>Security / Engineering Leadership</td></tr></tbody></table>',119)])])}const m=i(r,[["render",o]]);export{h as __pageData,m as default};
